"""Safe PoC generator — produces reproducible, non-destructive proof-of-concept scripts.

Each PoC is read-only/idempotent by default. Destructive PoCs (POST/PUT/DELETE)
require explicit operator confirmation before generation.
"""

from __future__ import annotations

from datetime import datetime, timezone


DISCLAIMER = """\
# PROOF OF CONCEPT — FOR AUTHORIZED TESTING ONLY
# Generated by pentest-plugin on {date}
# Finding: {finding_id} — {title}
# Target: {target}
# This PoC is for verification purposes during an authorized engagement.
# Do NOT execute without explicit authorization from the asset owner.
"""

CURL_TEMPLATE = """\
{disclaimer}
#!/bin/bash
set -euo pipefail

TARGET="{target}"

echo "[*] PoC for: {title}"
echo "[*] Vuln class: {vuln_class}"
echo "[*] Target: $TARGET"
echo ""

{commands}

echo ""
echo "[*] PoC complete. Review output above for evidence."
"""

PYTHON_TEMPLATE = """\
{disclaimer}
import requests
import sys
import urllib3
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

TARGET = "{target}"

def main():
    print(f"[*] PoC for: {title}")
    print(f"[*] Vuln class: {vuln_class}")
    print(f"[*] Target: {{TARGET}}")
    print()

{code}

    print()
    print("[*] PoC complete. Review output above for evidence.")

if __name__ == "__main__":
    main()
"""

NUCLEI_TEMPLATE = """\
id: poc-{finding_id}
info:
  name: "PoC: {title}"
  author: pentest-plugin
  severity: {severity}
  description: "Proof of concept for finding {finding_id}"
  tags: poc,autogenerated
  metadata:
    reviewed: false
    autogenerated: true
    generated_at: {date}
http:
  - method: GET
    path:
{paths}
    matchers-condition: and
    matchers:
      - type: status
        status: [{status_code}]
{extra_matchers}
"""


VULN_CLASS_POC_PATTERNS: dict[str, dict] = {
    "xss-reflected": {
        "curl": 'curl -sk "$TARGET{endpoint}?{param}=%3Cscript%3Ealert(1)%3C/script%3E" | grep -o "<script>alert(1)</script>" && echo "[+] XSS reflected in response" || echo "[-] Payload not reflected"',
        "safe": True,
    },
    "sqli": {
        "curl": "curl -sk \"$TARGET{endpoint}\" -d \"{param}=1' AND '1'='1\" -o /dev/null -w \"%{{http_code}}\" && echo \"[*] Response received — compare timing/status with normal request\"",
        "safe": True,
    },
    "ssrf": {
        "curl": 'curl -sk "$TARGET{endpoint}" -d "{param}=http://127.0.0.1:80" -w "\\nHTTP %{{http_code}}, Size: %{{size_download}}" && echo "\\n[*] Compare response size with normal request"',
        "safe": True,
    },
    "idor": {
        "curl": 'echo "[*] Testing IDOR with sequential IDs"\nfor id in 1 2 3; do\n  echo "ID=$id: $(curl -sk "$TARGET{endpoint}/$id" -w "HTTP %{{http_code}}, Size: %{{size_download}}" -o /dev/null)"\ndone\necho "[*] Different sizes/statuses indicate IDOR"',
        "safe": True,
    },
    "open-redirect": {
        "curl": 'REDIR=$(curl -sk -o /dev/null -w "%{{redirect_url}}" "$TARGET{endpoint}?{param}=https://evil.example.com")\necho "Redirect target: $REDIR"\n[[ "$REDIR" == *"evil.example.com"* ]] && echo "[+] Open redirect confirmed" || echo "[-] Redirect not followed"',
        "safe": True,
    },
    "info-disclosure": {
        "curl": 'curl -sk "$TARGET{endpoint}" | head -50\necho "\\n[*] Review above output for sensitive data"',
        "safe": True,
    },
    "cors-misconfiguration": {
        "curl": 'curl -sk "$TARGET{endpoint}" -H "Origin: https://evil.example.com" -D - -o /dev/null | grep -i "access-control-allow"\necho "[*] Check if evil.example.com is reflected in ACAO header"',
        "safe": True,
    },
}

UNSAFE_METHODS = {"POST", "PUT", "DELETE", "PATCH"}


class PoCGenerator:
    def generate_poc(self, finding: dict, format: str = "curl") -> str:
        vc = finding.get("vuln_class", "").lower()
        finding_id = finding.get("id", "UNKNOWN")
        title = finding.get("title", vc)
        target = finding.get("target_asset", "https://TARGET")
        severity = finding.get("severity", "medium")
        endpoint = finding.get("endpoint", "/")
        param = finding.get("parameter", "q")
        date = datetime.now(timezone.utc).strftime("%Y-%m-%d")

        disclaimer = DISCLAIMER.format(
            date=date, finding_id=finding_id, title=title, target=target,
        )

        if format == "curl":
            return self._generate_curl(finding, disclaimer)
        elif format == "python":
            return self._generate_python(finding, disclaimer)
        elif format == "nuclei":
            return self._generate_nuclei(finding)
        return f"# Unsupported format: {format}"

    def _generate_curl(self, finding: dict, disclaimer: str) -> str:
        vc = finding.get("vuln_class", "").lower()
        pattern = VULN_CLASS_POC_PATTERNS.get(vc)
        endpoint = finding.get("endpoint", "/")
        param = finding.get("parameter", "q")

        if pattern:
            commands = pattern["curl"].format(endpoint=endpoint, param=param)
        else:
            commands = f'curl -sk "$TARGET{endpoint}" -D - | head -30\necho "[*] Manual review required for {vc}"'

        return CURL_TEMPLATE.format(
            disclaimer=disclaimer,
            target=finding.get("target_asset", "https://TARGET"),
            title=finding.get("title", vc),
            vuln_class=vc,
            commands=commands,
        )

    def _generate_python(self, finding: dict, disclaimer: str) -> str:
        vc = finding.get("vuln_class", "").lower()
        endpoint = finding.get("endpoint", "/")
        param = finding.get("parameter", "q")

        code = (
            f'    resp = requests.get(f"{{TARGET}}{endpoint}", verify=False, timeout=10)\n'
            f'    print(f"Status: {{resp.status_code}}")\n'
            f'    print(f"Size: {{len(resp.content)}}")\n'
            f'    print(f"Headers: {{dict(resp.headers)}}")\n'
        )

        return PYTHON_TEMPLATE.format(
            disclaimer=disclaimer,
            target=finding.get("target_asset", "https://TARGET"),
            title=finding.get("title", vc),
            vuln_class=vc,
            code=code,
        )

    def _generate_nuclei(self, finding: dict) -> str:
        vc = finding.get("vuln_class", "").lower()
        endpoint = finding.get("endpoint", "/")

        paths = f'      - "{{{{BaseURL}}}}{endpoint}"'
        extra_matchers = (
            "      - type: word\n"
            "        part: body\n"
            "        words:\n"
            f'          - "{finding.get("detection_string", vc)}"'
        )

        return NUCLEI_TEMPLATE.format(
            finding_id=finding.get("id", "unknown"),
            title=finding.get("title", vc),
            severity=finding.get("severity", "medium"),
            date=datetime.now(timezone.utc).strftime("%Y/%m/%d"),
            paths=paths,
            status_code=200,
            extra_matchers=extra_matchers,
        )


def validate_poc_safety(poc_script: str) -> tuple[bool, list[str]]:
    """Check if a PoC script is safe (read-only/idempotent)."""
    warnings = []
    lowered = poc_script.lower()

    for method in UNSAFE_METHODS:
        if f"-x {method.lower()}" in lowered or f"method: {method.lower()}" in lowered:
            warnings.append(f"Uses {method} method — requires operator confirmation")
        if f'requests.{method.lower()}(' in lowered:
            warnings.append(f"Python requests.{method.lower()}() — requires operator confirmation")

    dangerous_patterns = [
        ("rm ", "File deletion command"),
        ("drop ", "Database drop command"),
        ("delete from", "Database delete command"),
        ("truncate ", "Database truncate command"),
        ("; rm", "Chained file deletion"),
        ("curl.*-d ", "POST data via curl (may be state-changing)"),
    ]
    for pattern, reason in dangerous_patterns:
        if pattern in lowered:
            warnings.append(reason)

    return (len(warnings) == 0, warnings)
